impl Solution{pub fn sort_transformed_array(n:Vec<i32>,a:i32,b:i32,c:i32)->Vec<i32>{fn f(x:i32,a:i32,b:i32,c:i32)->i32{a*x*x+b*x+c}let(mut l,mut h)=(0usize,n.len()-1);let mut r=vec![0;n.len()];if a>=0{let mut k=n.len()-1;while l<=h{let x=f(n[l],a,b,c);let y=f(n[h],a,b,c);if x>y{r[k]=x;l+=1}else{r[k]=y;if h==0{break}h-=1}if k==0{break}k-=1}}else{let mut k=0;while l<=h{let x=f(n[l],a,b,c);let y=f(n[h],a,b,c);if x<y{r[k]=x;l+=1}else{r[k]=y;if h==0{break}h-=1}k+=1;}}r}}
